# Let's manually analyze the inputs and outputs to understand the patterns
inputs = ['huah', 'dzv', 'auba', 'ijxu', 'hfdv']
outputs = ['hiwah', 'dhkvv', 'aihzdea', 'ijdiw', 'hfdv']

print("Input/Output pairs:")
for i in range(len(inputs)):
    print(f"  {inputs[i]} -> {outputs[i]}")

print("\nAnalyzing differences:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"  {inp} -> {out}")
    # Find where they differ
    for j in range(max(len(inp), len(out))):
        if j >= len(inp) or j >= len(out) or inp[j] != out[j]:
            print(f"    First difference at position {j}")
            if j < len(inp) and j < len(out):
                print(f"      '{inp[j]}' -> '{out[j]}'")
            elif j < len(inp):
                print(f"      '{inp[j]}' removed")
            else:
                print(f"      '{out[j]}' added")
            break

